from pathlib import Path
import json,re
root=Path(__file__).resolve().parents[1];assets=root/'assets'
old=(assets/'offline/pilami-hydra-vj.html').read_text();archive=json.loads(re.search(r'<script[^>]*data-offline-sources[^>]*>(.*?)</script>',old,re.S)[1])
sources={k:v for k,v in archive.items() if k.startswith('sources/hydra-synth/') or k in ['assets/vendor/LICENSE-Hydra.txt','sources/hydra-extensions/LICENSE-Metagrowing.txt','sources/hydra-extensions/LICENSE-Hyper-Hydra.txt']}
sources['Pilami-LICENSE.txt']=(assets/'vendor/LICENSE-Hydra.txt').read_text()
sources['pilami-public-export.js']=(assets/'pilami-public-export-0.39.51.js').read_text()
sources['pilami-hydra-extensions.js']=(assets/'pilami-hydra-extensions-0.28.0.js').read_text()
def safe_json(v):return json.dumps(v,ensure_ascii=False).replace('<','\\u003c')
def script(v):return re.sub(r'</script',r'<\\/script',v,flags=re.I)
html='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval' blob:; style-src 'unsafe-inline'; img-src data: blob:; media-src data: blob:; connect-src blob: data:; worker-src blob:; base-uri 'none'; form-action 'none'"><title>Pilami · Visuel</title><style>
:root{color-scheme:dark;font:14px system-ui,sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#05080d;color:#edf4ff}main{position:fixed;inset:0;display:grid;place-items:center}main>canvas{width:100%;height:100%;object-fit:contain;display:block}nav{position:fixed;right:16px;bottom:16px;display:flex;flex-wrap:wrap;justify-content:flex-end;max-width:calc(100vw - 32px);gap:7px;align-items:center;z-index:2;transition:opacity .3s}button{font:inherit;color:inherit;border:1px solid #ffffff35;border-radius:24px;padding:10px 14px;background:#101b2caa;backdrop-filter:blur(12px);cursor:pointer}button:hover,button:focus-visible{background:#263e5b;outline:2px solid #b6d8ff}.tools-hidden nav:not(:hover):not(:focus-within){opacity:0}#status{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);max-width:80vw;padding:20px;background:#101b2cee;border-radius:15px;z-index:3}dialog{max-width:min(560px,90vw);border:1px solid #61748d;border-radius:18px;background:#101b2c;color:inherit;padding:24px;line-height:1.65}dialog::backdrop{background:#000a}[hidden]{display:none!important}
</style></head><body><main data-pilami-strudel></main><p id="status" data-public-status role="status">Préparation du visuel…</p><nav aria-label="Lecture du visuel"><button type="button" data-public-pause aria-label="Pause" title="Pause">Ⅱ</button><button type="button" data-public-sound aria-pressed="false" hidden>Activer le son</button><button type="button" data-public-fullscreen title="Plein écran · F">Plein écran</button><button type="button" data-public-sources-button title="Sources et licences">Infos</button></nav><dialog data-public-sources-dialog><p>Visuel créé avec Pilami Strudel Lab et Hydra. Page autonome : le rendu est calculé dans ton navigateur.</p><p>Les réglages sont fixés lors de l’export. Les valeurs FFT restent à zéro : aucun micro ni appareil MIDI n’est sollicité. Les positions et mouvements de la simulation se recalculent à chaque ouverture.</p><p>Hydra et le lecteur Pilami : AGPL-3.0-or-later. Les crédits du preset et des extensions sont conservés dans les sources incluses.</p><button type="button" data-public-download-sources>Télécharger les sources et licences</button> <button type="button" data-public-close-sources>Fermer</button></dialog><script type="application/json" data-public-pack>{"__pilamiPublicPlaceholder":true}</script>'''
html+='<script type="application/json" data-public-sources>'+safe_json(sources)+'</script>'
for name in ['vendor/hydra-synth-1.3.29-pilami-0.11.4.js','pilami-hydra-extensions-0.28.0.js']:
 html+='<script>'+script((assets/name).read_text())+'</script>'
html+='<script data-public-runtime>'+script((assets/'offline/public-player-0.39.51.js').read_text())+'</script></body></html>'
(assets/'offline/pilami-hydra-public.html').write_text(html)
print('Public page template:',len(html.encode()),'bytes, sources:',len(sources))
